480: SendStream.prototype.send = function(path, stat){
481:   var options = this.options;
482:   var len = stat.size;
483:   var res = this.res;
484:   var req = this.req;
485:   var ranges = req.headers.range;
486:   var offset = options.start || 0;
487: 
488:   if (res._header) {
489:     // impossible to send now
490:     return this.headersAlreadySent();
491:   }
492: 
493:   debug('pipe "%s"', path)
494: 
495:   // set header fields
496:   this.setHeader(path, stat);
497: 
498:   // set content-type
499:   this.type(path);
500: 
501:   // conditional GET support
502:   if (this.isConditionalGET()
503:     && this.isCachable()
504:     && this.isFresh()) {
505:     return this.notModified();
506:   }
507: 
508:   // adjust len to start/end options
509:   len = Math.max(0, len - offset);
510:   if (options.end !== undefined) {
511:     var bytes = options.end - offset + 1;
512:     if (len > bytes) len = bytes;
513:   }
514: 
515:   // Range support
516:   if (ranges) {
517:     ranges = parseRange(len, ranges);
518: 
519:     // If-Range support
520:     if (!this.isRangeFresh()) {
521:       debug('range stale');
522:       ranges = -2;
523:     }
524: 
525:     // unsatisfiable
526:     if (-1 == ranges) {
527:       debug('range unsatisfiable');
528:       res.setHeader('Content-Range', 'bytes */' + stat.size);
529:       return this.error(416);
530:     }
531: 
532:     // valid (syntactically invalid/multiple ranges are treated as a regular response)
533:     if (-2 != ranges && ranges.length === 1) {
534:       debug('range %j', ranges);
535: 
536:       options.start = offset + ranges[0].start;
537:       options.end = offset + ranges[0].end;
538: 
539:       // Content-Range
540:       res.statusCode = 206;
541:       res.setHeader('Content-Range', 'bytes '
542:         + ranges[0].start
543:         + '-'
544:         + ranges[0].end
545:         + '/'
546:         + len);
547:       len = options.end - options.start + 1;
548:     }
549:   }
550: 
551:   // content-length
552:   res.setHeader('Content-Length', len);
553: 
554:   // HEAD support
555:   if ('HEAD' == req.method) return res.end();
556: 
557:   this.stream(path, options);
558: };
